/*
 * TM4C123 Simulator test fixture — device-header-layout.c
 *
 * Compile-time check that every register in the original device header sits
 * at its data-sheet offset (TM4C123GH6PM SPMS376E) and every core register at
 * its ARMv7-M offset. A wrong offset is a compile error, so the compiler test
 * that builds this file fails.
 */
#include <stddef.h>
#include "TM4C123.h"

#define CHECK(type, member, offset) _Static_assert(offsetof(type, member) == (offset), #type "." #member)

